<script setup>
import { useForm } from '@inertiajs/vue3'
import AdminLayout from '@/Layouts/AdminLayout.vue'
const props=defineProps({settings:{type:Object,default:()=>({})}})
const form=useForm({company_name:props.settings.company_name||'',phone:props.settings.phone||'',email:props.settings.email||'',address:props.settings.address||'',facebook:props.settings.facebook||'',linkedin:props.settings.linkedin||'',instagram:props.settings.instagram||'',footer_text:props.settings.footer_text||''})
function submit(){form.post('/admin/settings')}
</script>
<template><AdminLayout><div class="p-6 lg:p-8"><div class="mb-6"><h1 class="text-2xl font-semibold text-heritage-navy">Site Settings</h1><p class="mt-1 text-sm text-slate-500">Manage global company and footer information.</p></div><form @submit.prevent="submit" class="max-w-3xl space-y-5 rounded-lg border bg-white p-6"><label class="block"><span class="text-sm font-medium">Company Name</span><input v-model="form.company_name" class="mt-1 w-full rounded border p-3"></label><div class="grid gap-5 md:grid-cols-2"><label class="block"><span class="text-sm font-medium">Phone</span><input v-model="form.phone" class="mt-1 w-full rounded border p-3"></label><label class="block"><span class="text-sm font-medium">Email</span><input v-model="form.email" type="email" class="mt-1 w-full rounded border p-3"></label></div><label class="block"><span class="text-sm font-medium">Address</span><textarea v-model="form.address" rows="3" class="mt-1 w-full rounded border p-3"></textarea></label><div class="grid gap-5 md:grid-cols-3"><input v-model="form.facebook" placeholder="Facebook URL" class="rounded border p-3"><input v-model="form.linkedin" placeholder="LinkedIn URL" class="rounded border p-3"><input v-model="form.instagram" placeholder="Instagram URL" class="rounded border p-3"></div><label class="block"><span class="text-sm font-medium">Footer Text</span><textarea v-model="form.footer_text" rows="3" class="mt-1 w-full rounded border p-3"></textarea></label><button class="btn-gold">Save Settings</button></form></div></AdminLayout></template>